for _language_code, _messages in _INSIGHT_CATALOGS.items():
    _CATALOGS[_language_code].update(_messages)

_MONTHS = {
    "en": ("January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"),
    "es": ("enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"),
    "fr": ("janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre", "octobre", "novembre", "décembre"),
}

_MONTH_ABBREVIATIONS = {
    "en": ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"),
    "es": ("ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"),
    "fr": ("jan", "fév", "mar", "avr", "mai", "juin", "juil", "août", "sep", "oct", "nov", "déc"),
}


def current_language() -> str:
    try:
        code = app.storage.user.get("language", DEFAULT_LANGUAGE)
    except RuntimeError:
        return DEFAULT_LANGUAGE
    return code if code in LANGUAGE_BY_CODE else DEFAULT_LANGUAGE


def translate(message: str, /, *, language: str | None = None, **values) -> str:
    code = language or current_language()
    translated = _CATALOGS.get(code, {}).get(message, message)
    return translated.format(**values) if values else translated


def translated_options(values: list[str] | tuple[str, ...]) -> dict[str, str]:
    return {value: translate(value) for value in values}


def month_name(value: str | date | datetime, *, short: bool = False, language: str | None = None) -> str:
    parsed = datetime.strptime(value, "%Y-%m") if isinstance(value, str) else value
    code = language or current_language()
    name = _MONTHS.get(code, _MONTHS[DEFAULT_LANGUAGE])[parsed.month - 1]
    if short:
        name = _MONTH_ABBREVIATIONS.get(
            code, _MONTH_ABBREVIATIONS[DEFAULT_LANGUAGE]
        )[parsed.month - 1]
    return f"{name} {parsed.year}"


def date_name(value: str | date | datetime, *, include_year: bool = False, language: str | None = None) -> str:
    parsed = datetime.fromisoformat(value) if isinstance(value, str) else value
    code = language or current_language()
    name = _MONTH_ABBREVIATIONS.get(
        code, _MONTH_ABBREVIATIONS[DEFAULT_LANGUAGE]
    )[parsed.month - 1]
    if code == "en":
        return f"{name} {parsed.day}{f', {parsed.year}' if include_year else ''}"
    return f"{parsed.day} {name}{f' {parsed.year}' if include_year else ''}"


def configure_document() -> None:
    language = LANGUAGE_BY_CODE[current_language()]
    ui.run_javascript(
        f"document.documentElement.lang={language.code!r};"
        "document.documentElement.dir='ltr';document.body.dir='ltr';"
    )


def set_language(code: str) -> None:
    if code not in LANGUAGE_BY_CODE:
        raise ValueError("Unsupported language")
    app.storage.user["language"] = code


def language_options() -> dict[str, str]:
    return {language.code: language.native_name for language in LANGUAGES}


def catalog_keys(language: str) -> set[str]:
    return set(_CATALOGS.get(language, {}))
